     1→/**
     2→ * Operations Service - API calls for Operations department
     3→ */
     4→import apiClient from '../api/clients/apiClient';
     5→import type {
     6→  ContractGenerationRequest,
     7→  ContractGeneration,
     8→  OperationsFilterParams,
     9→  CotizacionData,
    10→  SolicitudDesembolsoRequest,
    11→} from '../types/legal';
    12→
    13→const BASE_URL = '/operations';
    14→
    15→export const operationsService = {
    16→  /**
    17→   * Request contract generation (Operations initiates)
    18→   */
    19→  async requestContractGeneration(
    20→    request: ContractGenerationRequest
    21→  ): Promise<ContractGeneration> {
    22→    // Create FormData for multipart/form-data (backend expects Form parameters)
    23→    const formData = new FormData();
    24→    formData.append('client_nit', request.client_nit);
    25→    formData.append('contract_type', request.contract_type || 'activos');
    26→
    27→    const response = await apiClient.post<ContractGeneration>(
    28→      `${BASE_URL}/contracts/generate`,
    29→      formData,
    30→      {
    31→        headers: {
    32→          'Content-Type': 'multipart/form-data',
    33→        },
    34→      }
    35→    );
    36→    return response.data;
    37→  },
    38→
    39→  /**
    40→   * Get all approved contracts with optional filters
    41→   * @param filters - Optional filter parameters
    42→   * @param sortBy - Optional field to sort by
    43→   * @param sortOrder - Optional sort order ('asc' or 'desc')
    44→   */
    45→  async getApprovedContracts(
    46→    filters?: OperationsFilterParams,
    47→    sortBy?: string,
    48→    sortOrder?: string
    49→  ): Promise<ContractGeneration[]> {
    50→    const params: Record<string, string | number> = {};
    51→
    52→    // Add filter parameters
    53→    if (filters) {
    54→      // Handle contract_types array - send as single contract_type for now
    55→      // Backend expects single contract_type, frontend will handle multi-select UI
    56→      if (filters.contract_types && filters.contract_types.length > 0) {
    57→        // For now, if multiple types selected, don't filter by type (show all)
    58→        // If single type, filter by that type
    59→        if (filters.contract_types.length === 1) {
    60→          params.contract_type = filters.contract_types[0];
    61→        }
    62→      }
    63→
    64→      if (filters.client_name) {
    65→        params.client_name = filters.client_name;
    66→      }
    67→      if (filters.client_nit) {
    68→        params.client_nit = filters.client_nit;
    69→      }
    70→      if (filters.date_from) {
    71→        params.date_from = filters.date_from;
    72→      }
    73→      if (filters.date_to) {
    74→        params.date_to = filters.date_to;
    75→      }
    76→      if (filters.cupo_min !== undefined) {
    77→        params.cupo_min = filters.cupo_min;
    78→      }
    79→      if (filters.cupo_max !== undefined) {
    80→        params.cupo_max = filters.cupo_max;
    81→      }
    82→    }
    83→
    84→    // Add sorting parameters
    85→    if (sortBy) {
    86→      params.sort_by = sortBy;
    87→    }
    88→    if (sortOrder) {
    89→      params.sort_order = sortOrder;
    90→    }
    91→
    92→    const response = await apiClient.get<ContractGeneration[]>(
    93→      `${BASE_URL}/contracts/approved`,
    94→      { params }
    95→    );
    96→    return response.data;
    97→  },
    98→
    99→  /**
   100→   * Request Otrosí contract generation (Operations initiates)
   101→   */
   102→  async requestOtrosiGeneration(
   103→    clientNit: string
   104→  ): Promise<ContractGeneration> {
   105→    // Create FormData for multipart/form-data (backend expects Form parameters)
   106→    const formData = new FormData();
   107→    formData.append('client_nit', clientNit);
   108→    formData.append('contract_type', 'otrosi');
   109→
   110→    const response = await apiClient.post<ContractGeneration>(
   111→      `${BASE_URL}/contracts/generate`,
