   125→  async getApprovedOtrosis(): Promise<ContractGeneration[]> {
   126→    return this.getApprovedContracts({ contract_types: ['otrosi'] });
   127→  },
   128→
   129→  /**
   130→   * Request Inventario Bodega contract generation with RUT upload (Operations initiates)
   131→   *
   132→   * @param clientNit - Client NIT
   133→   * @param rutFile - RUT PDF document for custodian operator
   134→   */
   135→  async requestInventarioBodegaGeneration(
   136→    clientNit: string,
